from functools import wraps
def decorate(f):
    @wraps(f)
    def wrapper():
        return f()
    return wrapper
@decorate
def score():
    return 8


def main():
    print(score.__name__)


if __name__ == "__main__":
    main()

def plus_one(f):
    return lambda: f() + 1
def twice(f):
    return lambda: 2 * f()
@twice
@plus_one
def value():
    return 3


def main():
    print(value())


if __name__ == "__main__":
    main()
